        return out

    frow = sum(r for r, c in fours) / len(fours)
    fcol = sum(c for r, c in fours) / len(fours)
    srow = sum(r for r, c in sixes) / len(sixes)
    scol = sum(c for r, c in sixes) / len(sixes)

    if abs(srow - frow) >= abs(scol - fcol):
        edge = max(r for r, c in fours) if srow > frow else min(r for r, c in fours)
